/** `icon:名称` 语法：名称支持字母数字下划线连字符，须以字母开头 */
const ICON_RE = /\bicon:([A-Za-z][A-Za-z0-9_-]*)/g;

/** 自定义元素名：经 react-markdown components 映射为图标 span */
export const RESUME_ICON_TAG = 'resume-icon';

/** 最小结构化节点类型，与 remarkResumeCols 的约定一致 */
interface MiniNode {
  type: string;
  value?: string;
  children?: MiniNode[];
  data?: {
    hName?: string;
    hProperties?: Record<string, unknown>;
  };
  [key: string]: unknown;
}

/** 把文本按 `icon:名称` 切分为 [文本 | 图标节点 | 文本...]；
 *  仅替换映射中存在的名称，未知名称保留原文 */
function splitIconText(value: string, icons: Record<string, string>): MiniNode[] {
  const out: MiniNode[] = [];
  let last = 0;
  ICON_RE.lastIndex = 0;
  for (let m = ICON_RE.exec(value); m; m = ICON_RE.exec(value)) {
    if (!icons[m[1]]) continue;
    if (m.index > last) out.push({ type: 'text', value: value.slice(last, m.index) });
    out.push({
      type: 'resumeIcon',
      data: { hName: RESUME_ICON_TAG, hProperties: { name: m[1] } },
      children: [],
    });
    last = m.index + m[0].length;
  }
  if (out.length === 0) return [{ type: 'text', value }];
  if (last < value.length) out.push({ type: 'text', value: value.slice(last) });
  return out;
}

/** remark 插件工厂：返回 remark 插件（被调用时返回 transformer）。
 *  遍历文本节点，把 `icon:名称` 替换为图标节点。
 *  icons 为「内置 + 自定义」合并后的映射（getIconMap 生成） */
export function remarkResumeIcons(icons: Record<string, string>) {
  return () => {
    const visit = (node: MiniNode): void => {
      const children = node.children;
      if (!children) return;
      for (let i = 0; i < children.length; i++) {
        const child = children[i];
        if (child.type === 'text' && typeof child.value === 'string' && child.value.includes('icon:')) {
          const parts = splitIconText(child.value, icons);
          if (parts.length > 1 || parts[0].type !== 'text') {
            children.splice(i, 1, ...parts);
            i += parts.length - 1;
          }
        } else {
          visit(child);
        }
      }
    };
    return (tree: MiniNode): void => {
      visit(tree);
    };
  };
}

/** 合并内置与自定义图标 */
export function getIconMap(customIcons?: Record<string, string>): Record<string, string> {
  return customIcons ? { ...BUILTIN_ICONS, ...customIcons } : BUILTIN_ICONS;
}

/** 自定义 SVG 白名单：标签与属性（防注入 script / 事件处理器） */
const ALLOWED_TAGS = new Set([
  'svg', 'path', 'g', 'circle', 'ellipse', 'rect', 'line', 'polyline', 'polygon', 'defs', 'title',
]);
const ALLOWED_ATTRS = new Set([
  'viewbox', 'd', 'fill', 'stroke', 'stroke-width', 'stroke-linecap', 'stroke-linejoin',
  'transform', 'cx', 'cy', 'r', 'rx', 'ry', 'x', 'y', 'x1', 'x2', 'y1', 'y2',
  'points', 'opacity', 'fill-rule', 'clip-rule', 'fill-opacity', 'stroke-opacity', 'version',
]);

/** 清理用户提供的自定义 SVG：白名单过滤标签/属性，剥离 script 与事件处理器。
 *  解析失败或不含任何图形元素时返回 null */
export function sanitizeCustomSvg(source: string): string | null {
  if (typeof DOMParser === 'undefined') return null;
  const doc = new DOMParser().parseFromString(source, 'image/svg+xml');
  if (doc.querySelector('parsererror')) return null;
  const root = doc.documentElement;
  if (!root || root.tagName.toLowerCase() !== 'svg') return null;

  const walk = (el: Element): void => {
    for (const attr of Array.from(el.attributes)) {
      const name = attr.name.toLowerCase();
      const isStyleLike = name.startsWith('on') || name === 'style' || name === 'href' || name === 'xlink:href';
      if (isStyleLike || !ALLOWED_ATTRS.has(name)) el.removeAttribute(attr.name);
    }
    for (const child of Array.from(el.children)) {
      if (!ALLOWED_TAGS.has(child.tagName.toLowerCase())) {
        child.remove();
        continue;
      }
      walk(child);
    }
  };
  walk(root);

  if (root.querySelector('path, circle, ellipse, rect, line, polyline, polygon') === null) return null;
  if (!root.getAttribute('viewBox')) {
    const w = root.getAttribute('width') || '1024';
    const h = root.getAttribute('height') || '1024';
    root.setAttribute('viewBox', `0 0 ${parseFloat(w) || 1024} ${parseFloat(h) || 1024}`);
  }
  root.setAttribute('fill', 'currentColor');
  root.removeAttribute('width');
  root.removeAttribute('height');
  root.removeAttribute('id');
  root.removeAttribute('class');
  return root.outerHTML;
}
